package com.bank.compat.model;

// A single field: name, type, and whether it has a default (so it is optional).
public class FieldDef {
    private final String name;
    private final String type;
    private final boolean hasDefault;

    public FieldDef(String name, String type, boolean hasDefault) {
        this.name = name;
        this.type = type;
        this.hasDefault = hasDefault;
    }

    public String getName() { return name; }
    public String getType() { return type; }
    public boolean hasDefault() { return hasDefault; }

    @Override public String toString() {
        return name + ":" + type + (hasDefault ? " (default)" : " (required)");
    }
}
