package com.bank.compat.model;

import java.util.List;

public class SchemaVersion {
    private final int version;
    private final List<FieldDef> fields;

    public SchemaVersion(int version, List<FieldDef> fields) {
        this.version = version;
        this.fields = fields;
    }

    public int getVersion() { return version; }
    public List<FieldDef> getFields() { return fields; }

    public FieldDef find(String name) {
        return fields.stream().filter(f -> f.getName().equals(name)).findFirst().orElse(null);
    }
}
