package com.bank.compat.registry;

import com.bank.compat.model.FieldDef;
import com.bank.compat.model.SchemaVersion;

// Simulates the registry compatibility rules between an old and a new schema.
public class CompatChecker {

    // Can a reader on NEW read data written with OLD?  (BACKWARD)
    private boolean backwardOk(SchemaVersion oldV, SchemaVersion newV) {
        for (FieldDef nf : newV.getFields()) {
            FieldDef of = oldV.find(nf.getName());
            // field is new in NEW and OLD data lacks it: needs a default
            if (of == null && !nf.hasDefault()) return false;
        }
        return true;
    }

    // Can a reader on OLD read data written with NEW?  (FORWARD)
    private boolean forwardOk(SchemaVersion oldV, SchemaVersion newV) {
        for (FieldDef of : oldV.getFields()) {
            FieldDef nf = newV.find(of.getName());
            // field removed in NEW and OLD reader still expects it: needs a default on OLD side
            if (nf == null && !of.hasDefault()) return false;
        }
        return true;
    }

    public boolean isCompatible(CompatMode mode, SchemaVersion oldV, SchemaVersion newV) {
        switch (mode) {
            case BACKWARD: return backwardOk(oldV, newV);
            case FORWARD:  return forwardOk(oldV, newV);
            case FULL:     return backwardOk(oldV, newV) && forwardOk(oldV, newV);
            case NONE:     return true; // no checking
            default:       return false;
        }
    }
}
