package com.bank.compat;

import com.bank.compat.model.FieldDef;
import com.bank.compat.model.SchemaVersion;
import com.bank.compat.registry.CompatChecker;
import com.bank.compat.registry.CompatMode;
import java.util.List;
import java.util.logging.*;

public class CompatDemo {
    private static final Logger log = Logger.getLogger(CompatDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        CompatChecker checker = new CompatChecker();

        SchemaVersion v1 = new SchemaVersion(1, List.of(
            new FieldDef("fromId", "string", false),
            new FieldDef("toId", "string", false),
            new FieldDef("amount", "bytes", false)));

        // Attempt 1: add REQUIRED currency (no default) — must be rejected under BACKWARD
        SchemaVersion v2Bad = new SchemaVersion(2, List.of(
            new FieldDef("fromId", "string", false),
            new FieldDef("toId", "string", false),
            new FieldDef("amount", "bytes", false),
            new FieldDef("currency", "string", false)));

        boolean bad = checker.isCompatible(CompatMode.BACKWARD, v1, v2Bad);
        if (!bad) {
            log.severe("REJECTED: adding required field 'currency' breaks BACKWARD compatibility "
                + "— old records have no value for it.");
        }

        // Attempt 2: add currency WITH default "INR" — accepted
        SchemaVersion v2Good = new SchemaVersion(2, List.of(
            new FieldDef("fromId", "string", false),
            new FieldDef("toId", "string", false),
            new FieldDef("amount", "bytes", false),
            new FieldDef("currency", "string", true))); // has default

        boolean good = checker.isCompatible(CompatMode.BACKWARD, v1, v2Good);
        log.info(() -> "currency with default INR under BACKWARD compatible=" + good);

        log.info("FULL check on v2Good=" + checker.isCompatible(CompatMode.FULL, v1, v2Good));
        log.info("NONE always allows=" + checker.isCompatible(CompatMode.NONE, v1, v2Bad));
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
